+    // Reset C to zero for correctness
+    for (int i = 0; i < n * n; ++i) C[i] = 0.0f;
+
+    // i-k-j loop order for good cache access pattern (Streaming B rows and C rows)
+    for (int i = 0; i < n; ++i) {
+        for (int k = 0; k < n; ++k) {
+            float a_ik = A[i * n + k];
+            // Vectorization on j loop (inner loop) using NEON for 4 floats
+            int j = 0;
+            // Process 4 elements at a time
+            for (; j <= n - 4; j += 4) {
+                // Load B[k, j..j+3] (4 elements - contiguous access along row k)
+                float b_vec[4] = {
+                    B[k * n + j], B[k * n + j + 1], 
+                    B[k * n + j + 2], B[k * n + j + 3]
+                };
+                
+                // Load C[i, j..j+3] (4 elements - contiguous access along row i)
+                float c_vec[4] = {
+                    C[i * n + j], C[i * n + j + 1], 
+                    C[i * n + j + 2], C[i * n + j + 3]
+                };
+
+                // C[i, j..j+3] += a_ik * B[k, j..j+3]
+                c_vec[0] += a_ik * b_vec[0];
+                c_vec[1] += a_ik * b_vec[1];
+                c_vec[2] += a_ik * b_vec[2];
+                c_vec[3] += a_ik * b_vec[3];
+                
+                // Store back to C
+                C[i * n + j] = c_vec[0];
+                C[i * n + j + 1] = c_vec[1];
+                C[i * n + j + 2] = c_vec[2];
+                C[i * n + j + 3] = c_vec[3];
+            }
+            // Handle remaining elements
+            for (; j < n; ++j) {
+                C[i * n + j] += a_ik * B[k * n + j];
+            }
         }
